/**
 * Clones a project into a new one of the same workspace, under the name,
 * slug and key the caller chose. When `includeIssues` is set, every live
 * issue of the source is copied; archived issues and comments never are.
 * Progress-tracking fields are reset on each copy, and the batch is gated
 * against the plan's issue quota before anything is written.
 */
export async function cloneProject(
  actor: Actor,
  input: CloneProjectInput,
): Promise<Project> {
  assertOrgScope(actor, input.orgId);

  const source = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertCan(actor, "project:read", projectResource(source));
  assertCan(actor, "project:create", orgResource(input.orgId));
  assertNotArchived("Project", source.id, source);

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  const usedProjects = await projectRepo.countProjects(input.orgId);
  if (wouldExceedLimit(org.plan, "projects", usedProjects)) {
    throw new Error(
      `Plan ${org.plan} allows ${usedProjects} projects; upgrade to add another`,
    );
  }

  const sourceIssues: Issue[] = [];
  if (input.includeIssues) {
    let cursor: string | null = null;
    for (;;) {
      const page = await issueRepo.listIssues({
        orgId: input.orgId,
        projectId: source.id,
        limit: 100,
        cursor,
      });
      sourceIssues.push(...page.items);
      if (page.nextCursor === null) break;
      cursor = page.nextCursor;
    }
  }

  if (
    sourceIssues.length > 0 &&
    wouldExceedLimit(org.plan, "issuesPerProject", 0, sourceIssues.length)
  ) {
    throw new Error(
      `Plan ${org.plan} does not allow copying ${sourceIssues.length} issues into one project`,
    );
  }

  const project = await projectRepo.insertProject({
    orgId: input.orgId,
    name: input.name,
    slug: input.slug,
    key: input.key,
    description: source.description,
    visibility: source.visibility,
    leadId: source.leadId,
    color: source.color,
    targetDate: null,
  });

  const ordered = [...sourceIssues].sort((a, b) => a.number - b.number);
  for (const [index, issue] of ordered.entries()) {
    await issueRepo.insertIssue(
      {
        orgId: input.orgId,
        projectId: project.id,
        title: issue.title,
        description: issue.description,
        status: ISSUE_STATUSES[0],
        priority: issue.priority,
        assigneeId: null,
        parentId: null,
        estimate: issue.estimate,
        dueAt: issue.dueAt,
        labelIds: issue.labelIds,
      },
      actor.userId,
      index + 1,
    );
  }

  await emit("project.cloned", {
    ...actorEnvelope(actor),
    projectId: project.id,
    sourceProjectId: source.id,
    issuesCopied: ordered.length,
  });

  return project;
}

/** Restore does not un-archive the issues: they are restored individually. */

